from scipy.optimize import least_squares
e=np.asarray(df['eps']);t=np.asarray(df['T']);s=np.asarray(df['sigma'])
forms={
'A':lambda p: p[0]*e**p[1]*np.exp(p[2]*t)+p[3]*np.exp(p[4]*t)+p[5]*e**p[6],
'B':lambda p: p[0]*e+p[1]*t**p[2]+p[3]*e*t**p[4],
'C':lambda p: p[0]*e**p[1]+p[2]*t**p[3]*np.exp(p[4]*e)+p[5],
'D':lambda p: p[0]*e**p[1]+p[2]*np.exp(p[3]*t)+p[4]*e**p[5]*np.exp(p[6]*t),
'E':lambda p: p[0]*e**p[1]*t**p[2]+p[3]*e**p[4]+p[5]*t**p[6],
'F':lambda p: p[0]*np.log(1+p[1]*e)+p[2]*t**p[3]+p[4]*e*np.exp(p[5]*t),
'G':lambda p: p[0]*e**p[1]*np.exp(p[2]/t)+p[3]*t**p[4]+p[5]*e,
'H':lambda p: p[0]*(1-np.exp(-p[1]*e))*t**p[2]+p[3]*e+p[4]*t,
}
